function proxyLines(u){
  const lines = u.models.map((m, i) => Object.assign(lineParts(m), { gear:(u.gear || [])[i] || [], base:baseOf(u, lineParts(m).name, i) }));
  // the Warlord and the enhancement on the character that has them (warlordOn / enhOn), else the first
  const on = (field, i) => u[field] ? whoOfLine(u, i) === u[field] : i === 0;
  const tagOf = i => [u.warlord && on('warlordOn', i) ? 'Warlord' : '', u.enhancement && on('enhOn', i) ? u.enhancement : ''].filter(Boolean);
  // the unit's short name is the first character's only
  const own = (l, words, i) => [i === 0 && l.name !== u.name && u.short ? u.short : baseName(l.name)].concat(words).join(' · ');
  if(lines.length === 1 && lines[0].n === 1) return [Object.assign(lines[0], { mark:own(lines[0], tagOf(0), 0), lead:true })];
  const nc = u.leads ? charsOf(u).length : 0;
  const body = lines.slice(nc);
  lines.slice(0, nc).forEach((l, i) => Object.assign(l, { mark:own(l, tagOf(i), i), lead:true }));
  const std = body.slice().sort((x, y) => y.n - x.n)[0];
  for(const l of body){
    if(l === std){ l.mark = 'standard'; l.std = true; continue; }
    const sb = baseName(std.name), lb = baseName(l.name);
    const named = lb === sb ? '' : lb.startsWith(sb + ' ') ? lb.slice(sb.length + 1) : lb;
    const cnt = (list, g) => list.filter(x => x === g).length;
    const more = [...new Set(l.gear)].filter(g => cnt(l.gear, g) > cnt(std.gear, g)).map(g => cnt(l.gear, g) > 1 ? cnt(l.gear, g) + '× ' + g : g);
    // a line named as the standard one: also what it has less of (a Boy with only a Slugga is not "standard")
    const less = named ? [] : [...new Set(std.gear)].filter(g => cnt(l.gear, g) < cnt(std.gear, g)).map(g => cnt(l.gear, g) ? cnt(l.gear, g) + '× ' + g : 'no ' + g);
    l.mark = [named, more.join(' + '), less.join(', '), l.extra].filter(Boolean).join(' · ') || 'standard';
  }
  return lines;
}
